                fprintf(stderr, "\n");
            fprintf(stderr, "%0.6lf ", A[i][j]);
        }
    fprintf(stderr, "\nend   dump: %s\n", "A");
    fprintf(stderr, "==END   DUMP_ARRAYS==\n");
}

int main() {

    int n = 30;
    int tsteps = 20;

    double A[30][30];
    double B[30][30];

    init_array(n, A, B);

    kernel_jacobi_2d(A, B);

    print_array(n, A);

    return 0;
}
